#!/usr/bin/env bash
# Start pydisplay's PyScript dev server and open a demo in the browser.
#
# Mirrors the primary CLI shapes of unix/micropython.exe:
#
#   micropython [<opts>] [-c <command> | -m <module> | <filename>]
#   micropython -i …    # REPL after running command/module/file
#
# Demo URLs come from web/pyscript/index.html (generated by
# scripts/gallery_generator.py) — the same micropython.html?modules=… /
# micropython.html?manifests=… links as the card grid; falls back to a
# minimal modules=/manifests= URL when an example has no gallery card.
#
# Usage (from repo root):
#   ./bin/pyscript.sh examples/calc_lvgl.py
#   ./bin/pyscript.sh -m examples.chango
#   ./bin/pyscript.sh                          # gallery
#   ./bin/pyscript.sh -i                       # REPL
#   ./bin/pyscript.sh examples/calc_lvgl.py -p 8080
#   ./bin/pyscript.sh examples/calc_lvgl.py --no-open
#   ./bin/pyscript.sh examples/calc_lvgl.py --kill-port
#   ./bin/pyscript.sh --modules bouncing_balls

set -euo pipefail

_SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PYDISPLAY_ROOT="${PYDISPLAY_ROOT:-$(cd "$_SCRIPT_DIR/.." && pwd)}"
SERVE="$PYDISPLAY_ROOT/tools/serve.py"
PYSCRIPT_DIR="$PYDISPLAY_ROOT/web/pyscript"
INDEX="$PYSCRIPT_DIR/index.html"
PORT=8000
FILE_ARG=""
MODULE_ARG=""
CODE_ARG=""
MODULES_ARG=""
MANIFESTS_ARG=""
DEPS_ARG=""
ENTRY_KIND=""    # file | module | code | sugar | ""
INTERACTIVE=0
OPEN=1
DEBUG=0
KILL_PORT=0
AUTOTEST=0
DURATION=5

usage() {
  cat <<EOF
Usage: ./bin/pyscript.sh [<opts>] [-c <code> | -m <module> | <file>]
       ./bin/pyscript.sh -i [<opts>]

Mirrors micropython/micropython.exe's primary CLI shapes.

  <file>            run examples/<name>.py — resolved against the gallery
                     card hrefs first, else a minimal modules=<name> URL.
                     Must be a file (a directory errors, like EISDIR); use
                     -m for packages.
  -m <module>       run examples.<name> or <name> — module or package under
                     src/examples/, resolved the same way as <file>. NOT a
                     bare directory path.
  -c <code>         not implemented for PyScript — there is no code-string
                     loader hook (query params only name modules/manifests
                     to import, not arbitrary source). Use -m/<file> instead.
  -i                open the REPL (web/pyscript/repl.html). Cannot combine
                     with a file/-m/--modules entry: the loader has no
                     run-then-REPL transition, so -i must be used alone.
  (nothing)         open the gallery index

  --modules NAME[,NAME...]     URL sugar: micropython.html?modules=…
  --manifests NAME[,NAME...]   URL sugar: micropython.html?manifests=…
  --deps NAME[,NAME...]        append &deps=… to whichever URL is resolved

  -p, --port PORT   port (default: 8000)
  --kill-port       kill any existing listener on PORT, then start serve.py
  --debug           open harness.html with the same query + debug=1
  --autotest        headless Playwright smoke (EXAMPLE_RESULT); implies --no-open.
                    Streams the page #log panel to stdout in real time.
  --auto-test       alias for --autotest
  --duration SEC    autotest duration seconds (default: 5)
  --no-open         start/reuse server and print URL; do not open a browser
  -h, --help        this help

If something is already listening on PORT, reuse it (do not bind again).
Use --kill-port when you want a fresh serve.py on that port.

Environment:
  PYDISPLAY_ROOT    pydisplay clone (default: parent of bin/)

Examples:
  ./bin/pyscript.sh examples/calc_lvgl.py
  ./bin/pyscript.sh -m examples.chango
  ./bin/pyscript.sh -m nano_gui_simpletest
  ./bin/pyscript.sh -i
  ./bin/pyscript.sh examples/calc_lvgl.py --kill-port
  ./bin/pyscript.sh --modules bouncing_balls --debug
EOF
}

set_entry() {
  local kind="$1"
  if [[ -n "$ENTRY_KIND" && "$ENTRY_KIND" != "$kind" ]]; then
    echo "pyscript.sh: cannot combine a ${ENTRY_KIND} entry with a ${kind} entry" >&2
    exit 1
  fi
  ENTRY_KIND="$kind"
}

while [[ $# -gt 0 ]]; do
  case "$1" in
    -h|--help)
      usage
      exit 0
      ;;
    -m)
      MODULE_ARG="${2:?-m requires a module name}"
      set_entry module
      shift 2
      ;;
    -c)
      CODE_ARG="${2:?-c requires a command string}"
      set_entry code
      shift 2
      ;;
    -i)
      INTERACTIVE=1
      shift
      ;;
    --modules)
      MODULES_ARG="${2:?--modules requires a value}"
      set_entry sugar
      shift 2
      ;;
    --manifests)
      MANIFESTS_ARG="${2:?--manifests requires a value}"
      set_entry sugar
      shift 2
      ;;
    --deps)
      DEPS_ARG="${2:?--deps requires a value}"
      shift 2
      ;;
    -p|--port)
      PORT="${2:?--port requires a number}"
      shift 2
      ;;
    --kill-port)
      KILL_PORT=1
      shift
      ;;
    --debug)
      DEBUG=1
      shift
      ;;
    --autotest|--auto-test)
      AUTOTEST=1
      OPEN=0
      shift
      ;;
    --duration)
      DURATION="${2:?--duration requires seconds}"
      shift 2
      ;;
    --no-open)
      OPEN=0
      shift
      ;;
    -*)
      echo "pyscript.sh: unknown option: $1" >&2
      usage >&2
      exit 1
      ;;
    *)
      if [[ -n "$FILE_ARG" ]]; then
        echo "pyscript.sh: unexpected argument: $1" >&2
        usage >&2
        exit 1
      fi
      FILE_ARG="$1"
      set_entry file
      shift
      ;;
  esac
done

if [[ "$ENTRY_KIND" == "code" ]]; then
  echo "pyscript.sh: -c is not supported for PyScript (no code-string loader hook)" >&2
  echo "pyscript.sh: pass a file (examples/<name>.py) or -m examples.<name> instead" >&2
  exit 1
fi

if [[ -n "$ENTRY_KIND" && "$INTERACTIVE" -eq 1 ]]; then
  echo "pyscript.sh: -i cannot be combined with a file/-m/--modules entry" >&2
  echo "pyscript.sh: the loader has no run-then-REPL transition; use -i alone to open the REPL" >&2
  exit 1
fi

if [[ "$AUTOTEST" -eq 1 && -z "$ENTRY_KIND" ]]; then
  echo "pyscript.sh: --autotest requires a file, -m module, or --modules/--manifests entry" >&2
  exit 1
fi

if [[ ! -f "$SERVE" ]]; then
  echo "pyscript.sh: serve.py not found: $SERVE" >&2
  exit 1
fi

if [[ ! -f "$INDEX" ]]; then
  echo "pyscript.sh: gallery index not found: $INDEX" >&2
  exit 1
fi

# Relative hrefs from index.html card links, e.g.
# micropython.html?modules=calc_lvgl,calc_engine or mp.html?manifests=car_cluster
# (mp.html/py.html are the chromeless "nochrome" variants of micropython.html/pyodide.html).
gallery_hrefs() {
  grep -oE 'href="(micropython|mp)\.html\?[^"]+"' "$INDEX" | sed 's/^href="//;s/"$//'
}

strip_html_prefix() {
  local q="$1"
  q="${q#micropython.html?}"
  q="${q#mp.html?}"
  printf '%s\n' "$q"
}

# Print matching href for NAME, or fail if none.
# kind: module | manifest
lookup_gallery_href() {
  local name="$1"
  local kind="$2"
  local href query
  local manifest_hit="" module_hit=""

  while IFS= read -r href; do
    [[ -z "$href" ]] && continue
    query="$(strip_html_prefix "$href")"
    case "$query" in
      manifests="${name}"|manifests="${name}"\&*)
        manifest_hit="$href"
        ;;
      modules="${name}"|modules="${name},"*|modules="${name}"\&*)
        module_hit="$href"
        ;;
    esac
  done < <(gallery_hrefs)

  if [[ "$kind" == "manifest" ]]; then
    [[ -n "$manifest_hit" ]] && { printf '%s\n' "$manifest_hit"; return 0; }
    return 1
  fi
  if [[ "$kind" == "module" ]]; then
    [[ -n "$module_hit" ]] && { printf '%s\n' "$module_hit"; return 0; }
    return 1
  fi
  return 1
}

list_gallery_demos() {
  local href query
  while IFS= read -r href; do
    query="$(strip_html_prefix "$href")"
    case "$query" in
      modules=*)
        query="${query#modules=}"
        query="${query%%&*}"
        printf '  %s\n' "${query%%,*}"
        ;;
      manifests=*)
        query="${query#manifests=}"
        query="${query%%&*}"
        printf '  %s\n' "$query"
        ;;
    esac
  done < <(gallery_hrefs)
}

# Resolve NAME (a bare example stem, no dots/slashes) + kind (module|manifest)
# to a relative href: prefer the gallery card, else a minimal URL when the
# backing file/manifest exists on disk.
lookup_or_build_url() {
  local stem="$1"
  local kind="$2"
  local href

  if href="$(lookup_gallery_href "$stem" "$kind")"; then
    printf '%s\n' "$href"
    return 0
  fi

  case "$kind" in
    manifest)
      if [[ -f "$PYDISPLAY_ROOT/packages/${stem}.json" ]] \
        && [[ -d "$PYDISPLAY_ROOT/src/examples/${stem}" ]]; then
        printf 'micropython.html?manifests=%s\n' "$stem"
        return 0
      fi
      ;;
    module)
      if [[ -f "$PYDISPLAY_ROOT/src/examples/${stem}.py" ]]; then
        printf 'micropython.html?modules=%s\n' "$stem"
        return 0
      fi
      ;;
  esac

  echo "pyscript.sh: no gallery card or ${kind} for '${stem}'" >&2
  echo "pyscript.sh: gallery demos:" >&2
  list_gallery_demos >&2
  return 1
}

# -m examples.<name> or -m <name> — top-level module/package under
# src/examples/ only (real micropython -m also runs submodules, but pydisplay
# demos are single-file or a package entry point, so that's all we resolve).
resolve_module_target() {
  local mod="$1"

  if [[ "$mod" == */* || "$mod" == /* ]]; then
    echo "pyscript.sh: -m takes a dotted module name (e.g. -m examples.chango), not a path: $mod" >&2
    return 1
  fi

  local stem="${mod##*.}"
  local prefix="${mod%.*}"
  if [[ "$prefix" != "$mod" && "$prefix" != "examples" ]]; then
    echo "pyscript.sh: unsupported module '$mod' — pyscript only runs top-level examples (examples.<name> or <name>)" >&2
    return 1
  fi

  if [[ -f "$PYDISPLAY_ROOT/src/examples/${stem}/__init__.py" ]]; then
    lookup_or_build_url "$stem" manifest
  elif [[ -f "$PYDISPLAY_ROOT/src/examples/${stem}.py" ]]; then
    lookup_or_build_url "$stem" module
  else
    echo "pyscript.sh: no such module: examples.${stem}" >&2
    echo "pyscript.sh: gallery demos:" >&2
    list_gallery_demos >&2
    return 1
  fi
}

# <file> — must be a flat file directly under src/examples/ (a directory, or
# a file nested inside an example package, errors: use -m for those).
resolve_file_target() {
  local file="$1"
  local resolved=""

  if [[ "$file" == /* ]]; then
    resolved="$file"
  elif [[ -e "$file" ]]; then
    resolved="$(cd "$(dirname -- "$file")" && pwd)/$(basename -- "$file")"
  elif [[ -e "$PYDISPLAY_ROOT/src/$file" ]]; then
    resolved="$PYDISPLAY_ROOT/src/$file"
  else
    echo "pyscript.sh: no such file: $file" >&2
    return 1
  fi

  if [[ -d "$resolved" ]]; then
    echo "pyscript.sh: $file: Is a directory (use -m examples.<name> to run a package)" >&2
    return 1
  fi
  if [[ ! -f "$resolved" ]]; then
    echo "pyscript.sh: no such file: $file" >&2
    return 1
  fi

  local src="$PYDISPLAY_ROOT/src"
  local rel=""
  case "$resolved" in
    "$src"/*) rel="${resolved#"$src"/}" ;;
    *)
      echo "pyscript.sh: '$file' is outside pydisplay src/ — pyscript can only launch example modules (examples/<name>.py)" >&2
      return 1
      ;;
  esac

  case "$rel" in
    examples/*.py)
      local mid="${rel#examples/}"
      mid="${mid%.py}"
      if [[ "$mid" == */* ]]; then
        echo "pyscript.sh: '$file' is inside an example package; use -m examples.${mid%%/*} instead" >&2
        return 1
      fi
      lookup_or_build_url "$mid" module
      ;;
    *)
      echo "pyscript.sh: '$file' is not under examples/ — pyscript can only launch example modules (examples/<name>.py)" >&2
      return 1
      ;;
  esac
}

build_sugar_url() {
  local parts=()
  [[ -n "$MODULES_ARG" ]] && parts+=("modules=${MODULES_ARG}")
  [[ -n "$MANIFESTS_ARG" ]] && parts+=("manifests=${MANIFESTS_ARG}")
  local IFS='&'
  printf 'micropython.html?%s\n' "${parts[*]}"
}

case "$ENTRY_KIND" in
  sugar)
    REL_PATH="$(build_sugar_url)"
    ;;
  module)
    REL_PATH="$(resolve_module_target "$MODULE_ARG")" || exit 1
    ;;
  file)
    REL_PATH="$(resolve_file_target "$FILE_ARG")" || exit 1
    ;;
  "")
    if [[ "$INTERACTIVE" -eq 1 ]]; then
      REL_PATH="repl.html"
    else
      REL_PATH="index.html"
    fi
    ;;
esac

if [[ -n "$DEPS_ARG" ]]; then
  case "$REL_PATH" in
    *\?*) REL_PATH="${REL_PATH}&deps=${DEPS_ARG}" ;;
    *) REL_PATH="${REL_PATH}?deps=${DEPS_ARG}" ;;
  esac
fi

BASE="http://127.0.0.1:${PORT}"
PAGE_ROOT="${BASE}/web/pyscript"

if [[ "$DEBUG" -eq 1 ]] || [[ "$AUTOTEST" -eq 1 ]]; then
  case "$REL_PATH" in
    micropython.html\?*)
      URL="${PAGE_ROOT}/harness.html?${REL_PATH#micropython.html?}"
      ;;
    mp.html\?*)
      URL="${PAGE_ROOT}/harness.html?${REL_PATH#mp.html?}"
      ;;
    *)
      URL="${PAGE_ROOT}/${REL_PATH}"
      ;;
  esac
  if [[ "$URL" == *"?"* ]]; then
    SEP="&"
  else
    SEP="?"
  fi
  if [[ "$DEBUG" -eq 1 ]]; then
    URL="${URL}${SEP}debug=1"
    SEP="&"
  fi
  if [[ "$AUTOTEST" -eq 1 ]]; then
    URL="${URL}${SEP}autotest=1&duration=${DURATION}"
  fi
else
  URL="${PAGE_ROOT}/${REL_PATH}"
fi

server_ready() {
  curl -sf -o /dev/null "${PAGE_ROOT}/micropython.html" 2>/dev/null
}

port_listening() {
  if command -v lsof >/dev/null 2>&1; then
    lsof -iTCP:"${PORT}" -sTCP:LISTEN >/dev/null 2>&1
    return $?
  fi
  if command -v ss >/dev/null 2>&1; then
    ss -ltn "( sport = :${PORT} )" 2>/dev/null | grep -q LISTEN
    return $?
  fi
  if command -v fuser >/dev/null 2>&1; then
    fuser "${PORT}/tcp" >/dev/null 2>&1
    return $?
  fi
  (echo >/dev/tcp/127.0.0.1/"${PORT}") >/dev/null 2>&1
}

stop_listener_on_port() {
  local pids=""
  if command -v lsof >/dev/null 2>&1; then
    pids="$(lsof -tiTCP:"${PORT}" -sTCP:LISTEN 2>/dev/null || true)"
  elif command -v fuser >/dev/null 2>&1; then
    echo "pyscript.sh: killing listener on port ${PORT}"
    fuser -k "${PORT}/tcp" 2>/dev/null || true
    sleep 0.5
    return 0
  elif command -v ss >/dev/null 2>&1; then
    pids="$(ss -ltnp "( sport = :${PORT} )" 2>/dev/null \
      | sed -n 's/.*pid=\([0-9][0-9]*\).*/\1/p' | sort -u || true)"
  fi
  if [[ -n "$pids" ]]; then
    echo "pyscript.sh: killing listener on port ${PORT} (pid ${pids//$'\n'/ })"
    # shellcheck disable=SC2086
    kill $pids 2>/dev/null || true
    sleep 0.5
  fi
}

wait_for_server() {
  local i
  for i in $(seq 1 50); do
    if server_ready; then
      return 0
    fi
    sleep 0.1
  done
  return 1
}

open_url() {
  local url="$1"
  if [[ "$OPEN" -eq 0 ]]; then
    return 0
  fi
  if command -v xdg-open >/dev/null 2>&1; then
    xdg-open "$url" >/dev/null 2>&1 &
  elif command -v wslview >/dev/null 2>&1; then
    wslview "$url" >/dev/null 2>&1 &
  elif [[ -n "${WSL_DISTRO_NAME:-}" ]] && command -v cmd.exe >/dev/null 2>&1; then
    cmd.exe /c start "" "$url" >/dev/null 2>&1 &
  else
    echo "pyscript.sh: no browser opener found; open manually:"
    echo "  $url"
    return 0
  fi
}

SERVER_PID=""
cleanup() {
  if [[ -n "$SERVER_PID" ]]; then
    kill "$SERVER_PID" 2>/dev/null || true
  fi
}
trap cleanup EXIT INT TERM

if [[ "$KILL_PORT" -eq 1 ]]; then
  stop_listener_on_port
  if port_listening; then
    echo "pyscript.sh: port ${PORT} still in use after --kill-port" >&2
    exit 1
  fi
fi

if [[ "$KILL_PORT" -eq 0 ]] && port_listening; then
  echo "pyscript.sh: reusing listener on ${BASE}"
  if ! server_ready; then
    echo "pyscript.sh: warning: port ${PORT} is in use but ${PAGE_ROOT}/micropython.html is not ready" >&2
    echo "pyscript.sh: use --kill-port to replace the listener" >&2
  fi
else
  echo "pyscript.sh: starting ${SERVE} on ${BASE}"
  python3 "$SERVE" -p "$PORT" &
  SERVER_PID=$!
  if ! wait_for_server; then
    echo "pyscript.sh: server did not become ready on ${BASE}" >&2
    exit 1
  fi
fi

echo "pyscript.sh: ${URL}"

if [[ "$AUTOTEST" -eq 1 ]]; then
  # Prefer repo venv Playwright; fall back to python3 on PATH.
  PY="${PYDISPLAY_ROOT}/.venv/bin/python"
  if [[ ! -x "$PY" ]]; then
    PY="python3"
  fi
  TIMEOUT_MS=$(( (DURATION + 40) * 1000 ))
  export PYSCRIPT_AUTOTEST_URL="$URL"
  export PYSCRIPT_AUTOTEST_DURATION="$DURATION"
  export PYSCRIPT_AUTOTEST_TIMEOUT_S="$(( DURATION + 40 ))"
  set +e
  "$PY" "${PYDISPLAY_ROOT}/tools/pyscript_autotest.py" "$URL" \
    --duration "$DURATION" \
    --timeout "$(( DURATION + 40 ))"
  rc=$?
  set -e
  exit "$rc"
fi

open_url "$URL"

if [[ -n "$SERVER_PID" ]]; then
  echo "pyscript.sh: Ctrl+C to stop the server"
  wait "$SERVER_PID"
fi
